def run_stage(tmp, name, source, args=(), cwd=None):
    f = tmp / name
    f.write_text(source, encoding='utf-8')
    print(f'--- v4.53 stage {name} ---', flush=True)
    subprocess.run([sys.executable, str(f), *[str(a) for a in args]],
                   cwd=str(cwd or tmp), check=True)


def main():
    assert JP.is_file(), f'target nahi mila: {JP} — patch ROK diya'
    original = JP.read_bytes()
    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td)
        stages = dict(STAGES)
        # Stage: java — argv SRC/DST; SRC ka naam 'built-v452b.java'
        # hote hi us ka MD5 guard fire hoga.
        (tmp / 'built-v452b.java').write_bytes(original)
        run_stage(tmp, 'stage_java.py', stages['stage_java.py'],
                  (tmp / 'built-v452b.java', tmp / 'built-v453.java'))
        final = (tmp / 'built-v453.java').read_bytes()
    fmd5 = hashlib.md5(final).hexdigest()
    assert fmd5 == '5e583d655d40252d7364f0401abcc613', \
        f'final MD5 galat: {fmd5} — patch ROK diya (kuch nahi likha)'
    JP.write_bytes(final)
    print(f'v4.53 java patch done: {JP} ({len(original)} -> {len(final)} bytes)')


if __name__ == '__main__':
    main()
